function makeId(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}
function stamp() {
  return new Date().toISOString();
}
function clean(value, fallback = "", limit = 1200) {
  if (typeof value !== "string") return fallback;
  const result = value.trim();
  return result ? result.slice(0, limit) : fallback;
}
function emptyData() {
  return { releases: [], checks: [], signals: [], risks: [], followUps: [], evidence: [] };
}
function readData() {
  if (typeof window === "undefined") return emptyData();
  try {
    return { ...emptyData(), ...JSON.parse(window.localStorage.getItem(STORAGE_KEY) || "{}") };
  } catch {
    return emptyData();
  }
}
function tone(value) {
  if (["pass", "resolved", "done", "low"].includes(value)) return "emerald";
  if (["fail", "blocked", "critical", "high"].includes(value)) return "rose";
  if (["running", "investigating", "medium", "in-progress"].includes(value)) return "amber";
  return "slate";
}
function Badge({ children, value }) {
  const colors = {
    slate: "border-slate-200 bg-slate-50 text-slate-700",
    emerald: "border-emerald-200 bg-emerald-50 text-emerald-800",
    amber: "border-amber-200 bg-amber-50 text-amber-800",
    rose: "border-rose-200 bg-rose-50 text-rose-800",
  };
  return <span className={`inline-flex rounded-full border px-2.5 py-1 text-[11px] font-semibold ${colors[tone(value)] || colors.slate}`}>{children}</span>;
}
function Button({ children, icon: Icon, onClick, variant = "secondary", type = "button" }) {
  const variants = {
    secondary: "border-slate-200 bg-white text-slate-700 hover:border-slate-300",
    primary: "border-cyan-600 bg-cyan-600 text-white hover:bg-cyan-700",
    danger: "border-rose-200 bg-white text-rose-700 hover:bg-rose-50",
  };
  return <button type={type} onClick={onClick} className={`inline-flex h-9 items-center justify-center gap-2 rounded-lg border px-3 text-xs font-semibold ${variants[variant]}`}>{Icon && <Icon size={14} />}{children}</button>;
}
function Field({ label, value, onChange, placeholder, options, required = false }) {
  const common = { value: value || "", onChange: (event) => onChange(event.target.value), required, className: "mt-1.5 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm outline-none focus:border-cyan-500" };
  return <label className="block text-xs font-semibold text-slate-700">{label}{options ? <select {...common}><option value="">Select...</option>{options.map((option) => <option key={option} value={option}>{option}</option>)}</select> : <input {...common} placeholder={placeholder} />}</label>;
}
function Area({ label, value, onChange, placeholder }) {
  return <label className="block text-xs font-semibold text-slate-700">{label}<textarea value={value || ""} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} rows={4} className="mt-1.5 w-full resize-y rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-cyan-500" /></label>;
}
function Empty({ title, description, action }) {
  return <div className="p-8 text-center"><p className="text-sm font-semibold text-slate-800">{title}</p><p className="mx-auto mt-1 max-w-md text-xs text-slate-500">{description}</p>{action && <div className="mt-4">{action}</div>}</div>;
}
function Section({ title, description, action, children }) {
  return <section className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-start justify-between gap-3 border-b border-slate-100 p-5"><div><h3 className="text-sm font-semibold text-slate-950">{title}</h3><p className="mt-1 text-xs text-slate-500">{description}</p></div>{action}</div>{children}</section>;
}
function Modal({ title, onClose, children }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b p-5"><h2 className="font-semibold">{title}</h2><button type="button" onClick={onClose}><X size={17} /></button></div><div className="p-5">{children}</div></div></div>;
}
function Stat({ icon: Icon, label, value, detail }) {
  return <article className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-3xl font-semibold">{value}</p></div><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-cyan-100 text-cyan-700"><Icon size={17} /></span></div><p className="mt-2 text-[11px] text-slate-500">{detail}</p></article>;
}

export default function TesterPostReleaseValidationWorkspace({ reports = [], onOpenReport }) {
  const [data, setData] = useState(emptyData);
  const [selectedId, setSelectedId] = useState("");
  const [tab, setTab] = useState("overview");
  const [query, setQuery] = useState("");
  const [ascending, setAscending] = useState(false);
  const [modal, setModal] = useState("");
  const [notice, setNotice] = useState("");
  const [releaseForm, setReleaseForm] = useState({ title: "", version: "", owner: "", environment: "", summary: "" });
  const [checkForm, setCheckForm] = useState({ title: "", domain: "Smoke", state: "planned", owner: "", evidence: "", result: "" });
  const [signalForm, setSignalForm] = useState({ title: "", state: "new", source: "", severity: "medium", detail: "" });
  const [riskForm, setRiskForm] = useState({ title: "", level: "medium", owner: "", mitigation: "", expiry: "" });
  const [followUpForm, setFollowUpForm] = useState({ title: "", state: "planned", owner: "", due: "", detail: "" });
  const [evidenceForm, setEvidenceForm] = useState({ title: "", kind: "Screenshot", reference: "", detail: "" });

  useEffect(() => setData(readData()), []);
  useEffect(() => { if (typeof window !== "undefined") window.localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }, [data]);
  useEffect(() => { if (!notice) return undefined; const timer = window.setTimeout(() => setNotice(""), 2500); return () => window.clearTimeout(timer); }, [notice]);

  const release = data.releases.find((item) => item.id === selectedId);
  const checks = data.checks.filter((item) => !selectedId || item.releaseId === selectedId);
  const signals = data.signals.filter((item) => !selectedId || item.releaseId === selectedId);
  const risks = data.risks.filter((item) => !selectedId || item.releaseId === selectedId);
  const followUps = data.followUps.filter((item) => !selectedId || item.releaseId === selectedId);
  const evidence = data.evidence.filter((item) => !selectedId || item.releaseId === selectedId);
  const passed = checks.filter((item) => item.state === "pass").length;
  const failed = checks.filter((item) => item.state === "fail").length;
  const blocked = checks.filter((item) => item.state === "blocked").length;
  const checkScore = checks.length ? Math.round((passed / checks.length) * 100) : 0;
  const activeRisks = risks.filter((item) => ["critical", "high", "medium"].includes(item.level));
  const openFollowUps = followUps.filter((item) => item.state !== "done");
  const filteredSignals = useMemo(() => signals.filter((item) => `${item.title} ${item.source} ${item.detail}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => { const result = a.title.localeCompare(b.title); return ascending ? result : result * -1; }), [ascending, query, signals]);

  function update(key, items) { setData((current) => ({ ...current, [key]: items })); }
  function addRelease(event) { event.preventDefault(); const item = { ...releaseForm, id: makeId("release"), title: clean(releaseForm.title), version: clean(releaseForm.version), owner: clean(releaseForm.owner), environment: clean(releaseForm.environment), summary: clean(releaseForm.summary), createdAt: stamp() }; update("releases", [item, ...data.releases]); setSelectedId(item.id); setReleaseForm({ title: "", version: "", owner: "", environment: "", summary: "" }); setModal(""); setNotice("Release validation workspace created"); }
  function addCheck(event) { event.preventDefault(); const item = { ...checkForm, id: makeId("check"), releaseId: selectedId, title: clean(checkForm.title), owner: clean(checkForm.owner), evidence: clean(checkForm.evidence), result: clean(checkForm.result), createdAt: stamp() }; update("checks", [item, ...data.checks]); setCheckForm({ title: "", domain: "Smoke", state: "planned", owner: "", evidence: "", result: "" }); setModal(""); setNotice("Validation check added"); }
  function addSignal(event) { event.preventDefault(); const item = { ...signalForm, id: makeId("signal"), releaseId: selectedId, title: clean(signalForm.title), source: clean(signalForm.source), detail: clean(signalForm.detail), createdAt: stamp() }; update("signals", [item, ...data.signals]); setSignalForm({ title: "", state: "new", source: "", severity: "medium", detail: "" }); setModal(""); setNotice("Customer signal added"); }
  function addRisk(event) { event.preventDefault(); const item = { ...riskForm, id: makeId("risk"), releaseId: selectedId, title: clean(riskForm.title), owner: clean(riskForm.owner), mitigation: clean(riskForm.mitigation), expiry: clean(riskForm.expiry), createdAt: stamp() }; update("risks", [item, ...data.risks]); setRiskForm({ title: "", level: "medium", owner: "", mitigation: "", expiry: "" }); setModal(""); setNotice("Residual risk added"); }
  function addFollowUp(event) { event.preventDefault(); const item = { ...followUpForm, id: makeId("follow-up"), releaseId: selectedId, title: clean(followUpForm.title), owner: clean(followUpForm.owner), due: clean(followUpForm.due), detail: clean(followUpForm.detail), createdAt: stamp() }; update("followUps", [item, ...data.followUps]); setFollowUpForm({ title: "", state: "planned", owner: "", due: "", detail: "" }); setModal(""); setNotice("Follow-up action added"); }
  function addEvidence(event) { event.preventDefault(); const item = { ...evidenceForm, id: makeId("evidence"), releaseId: selectedId, title: clean(evidenceForm.title), reference: clean(evidenceForm.reference), detail: clean(evidenceForm.detail), createdAt: stamp() }; update("evidence", [item, ...data.evidence]); setEvidenceForm({ title: "", kind: "Screenshot", reference: "", detail: "" }); setModal(""); setNotice("Validation evidence added"); }
  function change(key, itemId, field, value) { update(key, data[key].map((item) => item.id === itemId ? { ...item, [field]: value, updatedAt: stamp() } : item)); }
  function remove(key, itemId) { update(key, data[key].filter((item) => item.id !== itemId)); setNotice("Record removed"); }
  function applyPreset() { if (!selectedId) { setNotice("Select a release first"); return; } const items = VALIDATION_LIBRARY.slice(0, 30).map((title, index) => ({ id: makeId(`check-${index}`), releaseId: selectedId, title, domain: CHECK_DOMAINS[index % CHECK_DOMAINS.length], state: "planned", owner: "", evidence: "", result: "", createdAt: stamp() })); update("checks", [...items, ...data.checks]); setNotice("Post-release validation checklist applied"); }
  function copySummary() { navigator.clipboard?.writeText([`Release: ${release?.title || "All releases"}`, `Version: ${release?.version || "Not set"}`, `Validation score: ${checkScore}%`, `Passed: ${passed}`, `Failed: ${failed}`, `Blocked: ${blocked}`, `Customer signals: ${signals.length}`, `Residual risks: ${activeRisks.length}`, `Follow-ups: ${openFollowUps.length}`, release?.summary || "No summary recorded."].join("\n")); setNotice("Validation summary copied"); }
  function exportRows() { const rows = [["Type", "Title", "Domain", "State", "Owner", "Detail"], ...checks.map((item) => ["Check", item.title, item.domain, item.state, item.owner, item.result]), ...signals.map((item) => ["Signal", item.title, item.severity, item.state, item.source, item.detail]), ...risks.map((item) => ["Risk", item.title, item.level, "", item.owner, item.mitigation]), ...followUps.map((item) => ["Follow-up", item.title, "", item.state, item.owner, item.detail])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell || "").replaceAll('"', '""')}"`).join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "post-release-validation.csv"; anchor.click(); URL.revokeObjectURL(url); setNotice("Validation export downloaded"); }

  const tabs = [["overview", "Overview"], ["checks", `Checks (${checks.length})`], ["signals", `Signals (${signals.length})`], ["risks", `Risks (${risks.length})`], ["follow-ups", `Follow-ups (${followUps.length})`], ["evidence", `Evidence (${evidence.length})`]];
  return <section className="mt-8 space-y-5">
    <div className="rounded-3xl border border-cyan-200 bg-gradient-to-br from-cyan-50 via-white to-slate-50 p-5 shadow-sm sm:p-7"><div className="flex flex-col gap-5 lg:flex-row lg:justify-between"><div className="max-w-3xl"><div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.16em] text-cyan-700"><ShieldCheck size={16} /> Post-release validation</div><h2 className="mt-3 text-2xl font-semibold tracking-tight text-slate-950 sm:text-3xl">Verify that the release still behaves after the launch moment.</h2><p className="mt-3 text-sm leading-6 text-slate-600">Track production smoke checks, customer signals, residual risks, evidence, and follow-up work in a private tester workspace.</p></div><div className="flex flex-wrap gap-2"><Button icon={Plus} variant="primary" onClick={() => setModal("release")}>New validation</Button><Button icon={Copy} onClick={copySummary}>Copy summary</Button><Button icon={Download} onClick={exportRows}>Export</Button></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Stat icon={Gauge} label="Validation score" value={`${checkScore}%`} detail={`${passed} passing checks`} /><Stat icon={AlertCircle} label="Failures" value={failed} detail={`${blocked} blocked checks`} /><Stat icon={Flag} label="Residual risks" value={activeRisks.length} detail={`${risks.length} total risk records`} /><Stat icon={FileCheck2} label="Evidence" value={evidence.length} detail={`${openFollowUps.length} open follow-ups`} /></div></div>
    {notice && <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs font-semibold text-emerald-800">{notice}</div>}
    <div className="flex flex-wrap gap-2 border-b border-slate-200 pb-1">{tabs.map(([value, label]) => <button key={value} type="button" onClick={() => setTab(value)} className={`rounded-t-lg px-3 py-2 text-xs font-semibold ${tab === value ? "border-b-2 border-cyan-600 text-cyan-700" : "text-slate-500"}`}>{label}</button>)}</div>
    <Section title="Release validation context" description="Select the release or create a new post-release validation record." action={<Button icon={RefreshCw} onClick={() => { setData(readData()); setNotice("Validation workspace refreshed"); }}>Refresh</Button>}><div className="grid gap-4 p-5 lg:grid-cols-[minmax(0,1fr)_auto]"><label className="text-xs font-semibold text-slate-700">Selected release<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)} className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm"><option value="">All validation records</option>{data.releases.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><div className="flex items-end gap-2"><Button icon={ClipboardCheck} onClick={applyPreset}>Apply checklist</Button><Button icon={Plus} onClick={() => setModal("release")}>Add release</Button></div></div><div className="grid gap-3 border-t border-slate-100 p-5 md:grid-cols-2 xl:grid-cols-3">{data.releases.map((item) => <button key={item.id} type="button" onClick={() => setSelectedId(item.id)} className={`rounded-xl border p-4 text-left ${selectedId === item.id ? "border-cyan-300 bg-cyan-50" : "border-slate-200"}`}><div className="flex items-start justify-between gap-3"><p className="text-sm font-semibold">{item.title}</p><Badge value={item.version}>{item.version || "No version"}</Badge></div><p className="mt-2 line-clamp-2 text-xs text-slate-500">{item.summary || "No validation summary recorded."}</p><p className="mt-3 text-[11px] text-slate-400">{item.environment || "Environment not set"} · {item.owner || "Unassigned"}</p></button>)}{!data.releases.length && <div className="md:col-span-2 xl:col-span-3"><Empty title="No post-release validation" description="Create a validation record for a release, hotfix, or migration." action={<Button icon={Plus} variant="primary" onClick={() => setModal("release")}>Create validation</Button>} /></div>}</div></Section>
    {tab === "overview" && <div className="grid gap-5 xl:grid-cols-2"><Section title="Validation posture" description="A quick read of production confidence after release."><div className="space-y-4 p-5"><div className="rounded-xl border border-cyan-100 bg-cyan-50 p-4"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-cyan-900">Production check progress</p><p className="text-lg font-semibold text-cyan-900">{checkScore}%</p></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-white"><div className="h-full rounded-full bg-cyan-600" style={{ width: `${checkScore}%` }} /></div><p className="mt-3 text-xs text-cyan-800">{failed ? `${failed} failed check${failed === 1 ? "" : "s"} need investigation.` : "No failed checks recorded."}</p></div><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Signals</p><p className="mt-1 text-xl font-semibold">{signals.length}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Risks</p><p className="mt-1 text-xl font-semibold">{activeRisks.length}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Follow-ups</p><p className="mt-1 text-xl font-semibold">{openFollowUps.length}</p></div></div><p className="text-[11px] text-slate-500">Validation library: {VALIDATION_LIBRARY.length} reusable prompts across smoke, functional, browser, support, and recovery checks.</p></div></Section><Section title="Release narrative" description="Keep the post-release conclusion close to the evidence."><div className="space-y-4 p-5"><Area label="Summary" value={release?.summary || ""} onChange={(value) => release && change("releases", release.id, "summary", value)} placeholder="What did the release look like in production?" /><Area label="Conclusion" value={release?.conclusion || ""} onChange={(value) => release && change("releases", release.id, "conclusion", value)} placeholder="What is safe, what is uncertain, and what needs follow-up?" /></div></Section><Section title="Signals to watch" description="Post-release confidence is more than a single smoke test."><div className="grid gap-3 p-5 sm:grid-cols-2">{[["Customer voice", "Support contacts and feedback reveal experience gaps.", MessageSquareText], ["Operational health", "Errors, latency, queues, and alerts show stability.", Gauge], ["Journey coverage", "Critical paths need checks after real traffic arrives.", CheckCircle2], ["Ownership", "Every unexpected signal needs a responsible next step.", Users]].map(([title, detail, Icon]) => <div key={title} className="rounded-xl border border-slate-200 p-4"><Icon size={17} className="text-cyan-600" /><p className="mt-3 text-sm font-semibold">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{detail}</p></div>)}</div></Section><Section title="Recent reports" description="Open a report when it provides direct post-release evidence."><div className="divide-y border-t border-slate-100">{reports.slice(0, 5).map((report) => <div key={report.id} className="flex items-center justify-between gap-3 p-4"><div className="min-w-0"><p className="truncate text-sm font-semibold">{report.title || report.summary || `Report ${report.id}`}</p><p className="mt-1 text-[11px] text-slate-500">{report.severity || "Unclassified"} · {report.status || "Open"}</p></div><Button onClick={() => { onOpenReport?.(report); setNotice("Report opened"); }}>Open</Button></div>)}{!reports.length && <Empty title="No reports available" description="Loaded tester reports will appear here." />}</div></Section></div>}
    {tab === "checks" && <Section title="Post-release validation checks" description="Execute targeted checks against the live release." action={<Button icon={Plus} variant="primary" onClick={() => setModal("check")}>Add check</Button>}><div className="flex flex-wrap gap-2 border-b border-slate-100 p-5">{RELEASE_PRESETS.map((preset) => <button key={preset} type="button" onClick={() => setCheckForm((current) => ({ ...current, title: preset }))} className="rounded-full border border-slate-200 px-3 py-1.5 text-[11px] text-slate-600 hover:border-cyan-300 hover:text-cyan-700">{preset}</button>)}</div>{!checks.length ? <Empty title="No validation checks" description="Apply the reusable checklist or add a targeted production check." action={<Button icon={ClipboardCheck} onClick={applyPreset}>Apply checklist</Button>} /> : <div className="divide-y">{checks.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex flex-wrap items-center gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.state}>{item.state}</Badge><Badge value={item.domain}>{item.domain}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.result || item.evidence || "No result recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"}</p></div><div className="flex gap-2"><select value={item.state} onChange={(event) => change("checks", item.id, "state", event.target.value)} className="h-8 rounded-lg border border-slate-200 px-2 text-[11px]">{CHECK_STATES.map((state) => <option key={state} value={state}>{state}</option>)}</select><Button variant="danger" icon={Trash2} onClick={() => remove("checks", item.id)}>Remove</Button></div></div>)}</div>}</Section>}
    {tab === "signals" && <Section title="Customer and operational signals" description="Track what users, support, monitoring, and testers are reporting." action={<Button icon={Plus} variant="primary" onClick={() => setModal("signal")}>Add signal</Button>}><div className="flex gap-3 border-b border-slate-100 p-5"><div className="relative min-w-0 flex-1"><Search size={15} className="absolute left-3 top-3 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search signals, sources, details..." className="h-10 w-full rounded-lg border border-slate-200 pl-9 pr-3 text-sm" /></div><Button icon={ascending ? ArrowUpAZ : ArrowDownAZ} onClick={() => setAscending((value) => !value)}>Sort</Button></div>{!filteredSignals.length ? <Empty title="No signals recorded" description="Add a customer, support, tester, or monitoring signal." action={<Button icon={Plus} onClick={() => setModal("signal")}>Add signal</Button>} /> : <div className="divide-y">{filteredSignals.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:justify-between"><div><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.severity}>{item.severity}</Badge><Badge value={item.state}>{item.state}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.detail || "No detail recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Source: {item.source || "Unknown"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("signals", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "risks" && <Section title="Residual release risks" description="Capture what remains after production validation and who owns it." action={<Button icon={Plus} variant="primary" onClick={() => setModal("risk")}>Add risk</Button>}>{!risks.length ? <Empty title="No residual risks" description="Record an unresolved concern, accepted gap, or monitoring need." action={<Button icon={Plus} onClick={() => setModal("risk")}>Add risk</Button>} /> : <div className="divide-y">{risks.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:justify-between"><div><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.level}>{item.level}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.mitigation || "No mitigation recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"} · Expiry: {item.expiry || "Not set"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("risks", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "follow-ups" && <Section title="Post-release follow-ups" description="Turn observations into durable prevention and improvement work." action={<Button icon={Plus} variant="primary" onClick={() => setModal("follow-up")}>Add follow-up</Button>}>{!followUps.length ? <Empty title="No follow-ups recorded" description="Add a regression, monitoring, documentation, or ownership action." action={<Button icon={Plus} onClick={() => setModal("follow-up")}>Add follow-up</Button>} /> : <div className="divide-y">{followUps.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.state}>{item.state}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.detail || "No detail recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"} · Due: {item.due || "Not set"}</p></div><div className="flex gap-2"><select value={item.state} onChange={(event) => change("followUps", item.id, "state", event.target.value)} className="h-8 rounded-lg border border-slate-200 px-2 text-[11px]">{FOLLOW_UP_STATES.map((state) => <option key={state} value={state}>{state}</option>)}</select><Button variant="danger" icon={Trash2} onClick={() => remove("followUps", item.id)}>Remove</Button></div></div>)}</div>}</Section>}
    {tab === "evidence" && <Section title="Evidence index" description="Keep production proof and references available for review." action={<Button icon={Plus} variant="primary" onClick={() => setModal("evidence")}>Add evidence</Button>}>{!evidence.length ? <Empty title="No validation evidence" description="Add screenshots, logs, test results, recordings, or links." action={<Button icon={Plus} onClick={() => setModal("evidence")}>Add evidence</Button>} /> : <div className="divide-y">{evidence.map((item) => <div key={item.id} className="flex justify-between gap-3 p-5"><div><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.kind}>{item.kind}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.detail || "No detail recorded."}</p><p className="mt-2 text-[11px] text-cyan-700">{item.reference || "No reference recorded"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("evidence", item.id)}>Remove</Button></div>)}</div>}</Section>}
    <Section title="Validation prompts" description="Use these prompts to keep post-release review specific and repeatable."><div className="grid gap-2 p-5 sm:grid-cols-2 lg:grid-cols-3">{VALIDATION_LIBRARY.slice(0, 12).map((prompt) => <button key={prompt} type="button" onClick={() => { setTab("checks"); setCheckForm((current) => ({ ...current, title: prompt })); setNotice("Prompt loaded into check form"); }} className="rounded-lg border border-slate-200 px-3 py-2 text-left text-[11px] text-slate-600 hover:border-cyan-300 hover:text-cyan-700">{prompt}</button>)}</div><p className="px-5 pb-5 text-[11px] text-slate-400">The full library contains {VALIDATION_LIBRARY.length} prompts and remains local to this browser.</p></Section>
    <Section title="Release conclusion" description="Use a short, explicit conclusion for the release owner.">
      <div className="grid gap-3 p-5 sm:grid-cols-3">
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4">
          <p className="text-xs font-semibold text-emerald-800">Confirmed</p>
          <p className="mt-2 text-2xl font-semibold text-emerald-900">{passed}</p>
          <p className="mt-1 text-[11px] text-emerald-700">Checks passed</p>
        </div>
        <div className="rounded-xl border border-rose-200 bg-rose-50 p-4">
          <p className="text-xs font-semibold text-rose-800">Needs review</p>
          <p className="mt-2 text-2xl font-semibold text-rose-900">{failed + blocked}</p>
          <p className="mt-1 text-[11px] text-rose-700">Failed or blocked</p>
        </div>
        <div className="rounded-xl border border-cyan-200 bg-cyan-50 p-4">
          <p className="text-xs font-semibold text-cyan-800">Follow-up</p>
          <p className="mt-2 text-2xl font-semibold text-cyan-900">{openFollowUps.length}</p>
          <p className="mt-1 text-[11px] text-cyan-700">Actions still open</p>
        </div>
      </div>
    </Section>
    {modal === "release" && <Modal title="Create post-release validation" onClose={() => setModal("")}><form onSubmit={addRelease} className="space-y-4"><Field label="Validation title" value={releaseForm.title} onChange={(value) => setReleaseForm({ ...releaseForm, title: value })} placeholder="Release 2.4 production validation" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Version" value={releaseForm.version} onChange={(value) => setReleaseForm({ ...releaseForm, version: value })} placeholder="2.4.0" /><Field label="Environment" value={releaseForm.environment} onChange={(value) => setReleaseForm({ ...releaseForm, environment: value })} placeholder="Production" /><Field label="Owner" value={releaseForm.owner} onChange={(value) => setReleaseForm({ ...releaseForm, owner: value })} placeholder="Tester lead" /></div><Area label="Summary" value={releaseForm.summary} onChange={(value) => setReleaseForm({ ...releaseForm, summary: value })} placeholder="What is being validated after release?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Create validation</Button></div></form></Modal>}
    {modal === "check" && <Modal title="Add validation check" onClose={() => setModal("")}><form onSubmit={addCheck} className="space-y-4"><Field label="Check title" value={checkForm.title} onChange={(value) => setCheckForm({ ...checkForm, title: value })} placeholder="Confirm the primary checkout journey" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Domain" options={CHECK_DOMAINS} value={checkForm.domain} onChange={(value) => setCheckForm({ ...checkForm, domain: value })} /><Field label="State" options={CHECK_STATES} value={checkForm.state} onChange={(value) => setCheckForm({ ...checkForm, state: value })} /><Field label="Owner" value={checkForm.owner} onChange={(value) => setCheckForm({ ...checkForm, owner: value })} /><Field label="Evidence" value={checkForm.evidence} onChange={(value) => setCheckForm({ ...checkForm, evidence: value })} placeholder="Report, screenshot, or run" /></div><Area label="Result" value={checkForm.result} onChange={(value) => setCheckForm({ ...checkForm, result: value })} placeholder="Observed production result and notes." /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add check</Button></div></form></Modal>}
    {modal === "signal" && <Modal title="Add customer signal" onClose={() => setModal("")}><form onSubmit={addSignal} className="space-y-4"><Field label="Signal title" value={signalForm.title} onChange={(value) => setSignalForm({ ...signalForm, title: value })} placeholder="Support reports checkout failures" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="State" options={SIGNAL_STATES} value={signalForm.state} onChange={(value) => setSignalForm({ ...signalForm, state: value })} /><Field label="Severity" options={RISK_LEVELS} value={signalForm.severity} onChange={(value) => setSignalForm({ ...signalForm, severity: value })} /><Field label="Source" value={signalForm.source} onChange={(value) => setSignalForm({ ...signalForm, source: value })} placeholder="Support, monitoring, tester" /></div><Area label="Detail" value={signalForm.detail} onChange={(value) => setSignalForm({ ...signalForm, detail: value })} placeholder="What was observed and how reliable is it?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add signal</Button></div></form></Modal>}
    {modal === "risk" && <Modal title="Add residual risk" onClose={() => setModal("")}><form onSubmit={addRisk} className="space-y-4"><Field label="Risk title" value={riskForm.title} onChange={(value) => setRiskForm({ ...riskForm, title: value })} placeholder="Mobile notification delivery is not fully verified" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Level" options={RISK_LEVELS} value={riskForm.level} onChange={(value) => setRiskForm({ ...riskForm, level: value })} /><Field label="Owner" value={riskForm.owner} onChange={(value) => setRiskForm({ ...riskForm, owner: value })} /><Field label="Expiry" value={riskForm.expiry} onChange={(value) => setRiskForm({ ...riskForm, expiry: value })} placeholder="Next release" /></div><Area label="Mitigation" value={riskForm.mitigation} onChange={(value) => setRiskForm({ ...riskForm, mitigation: value })} placeholder="What monitoring or follow-up reduces this risk?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add risk</Button></div></form></Modal>}
    {modal === "follow-up" && <Modal title="Add follow-up action" onClose={() => setModal("")}><form onSubmit={addFollowUp} className="space-y-4"><Field label="Follow-up title" value={followUpForm.title} onChange={(value) => setFollowUpForm({ ...followUpForm, title: value })} placeholder="Add regression coverage for failed journey" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="State" options={FOLLOW_UP_STATES} value={followUpForm.state} onChange={(value) => setFollowUpForm({ ...followUpForm, state: value })} /><Field label="Owner" value={followUpForm.owner} onChange={(value) => setFollowUpForm({ ...followUpForm, owner: value })} /><Field label="Due" value={followUpForm.due} onChange={(value) => setFollowUpForm({ ...followUpForm, due: value })} placeholder="Next sprint" /></div><Area label="Detail" value={followUpForm.detail} onChange={(value) => setFollowUpForm({ ...followUpForm, detail: value })} placeholder="What will prevent recurrence?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add follow-up</Button></div></form></Modal>}
    {modal === "evidence" && <Modal title="Add validation evidence" onClose={() => setModal("")}><form onSubmit={addEvidence} className="space-y-4"><Field label="Evidence title" value={evidenceForm.title} onChange={(value) => setEvidenceForm({ ...evidenceForm, title: value })} placeholder="Production smoke result" required /><Field label="Kind" options={["Screenshot", "Recording", "Log", "Test result", "Report", "Link", "Note"]} value={evidenceForm.kind} onChange={(value) => setEvidenceForm({ ...evidenceForm, kind: value })} /><Field label="Reference" value={evidenceForm.reference} onChange={(value) => setEvidenceForm({ ...evidenceForm, reference: value })} placeholder="URL, report id, or file name" /><Area label="Detail" value={evidenceForm.detail} onChange={(value) => setEvidenceForm({ ...evidenceForm, detail: value })} placeholder="What does this evidence establish?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add evidence</Button></div></form></Modal>}
  </section>;
}
